import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"SDK concepts","description":"Native JSON flow, capabilities, adapters, delta magics, non-goals.","frontmatter":{"title":"SDK concepts","description":"Native JSON flow, capabilities, adapters, delta magics, non-goals."},"headers":[],"relativePath":"en/api/sdk/concepts.md","filePath":"en/api/sdk/concepts.md","lastUpdated":1790057721000}`),a={name:`en/api/sdk/concepts.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="sdk-concepts" tabindex="-1">SDK concepts <a class="header-anchor" href="#sdk-concepts" aria-label="Permalink to “SDK concepts”">​</a></h1><p>Cross-language reference. Language details live on each language page.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Native client JSON: check, download, verify, optional delta/pack, optional replace.</p><p>Non-goals: admin-plane SDK; Sparkle/WinGet/electron-updater/Play/App Store; OpenAPI-generated clients; browsers and Deno (TypeScript has no browser export).</p><h2 id="default-flow" tabindex="-1">Default flow <a class="header-anchor" href="#default-flow" aria-label="Permalink to “Default flow”">​</a></h2><ol><li>Caller identity parameters including a stable <code>device_id</code>. The SDK does not mint identity and does not log plaintext device ids.</li><li>Optional device report.</li><li>POST update check (default capability full package only).</li><li>Optional changelog (check has no body text).</li><li>Download <code>/packages/{sha256}</code> (keep <code>exp</code>/<code>sig</code>, support Range).</li><li>SHA-256; if <code>signature</code> is present, verify over the check payload.</li><li>Replace only with a Replacer; otherwise return the verified staging path.</li></ol><h2 id="check-and-http" tabindex="-1">Check and HTTP <a class="header-anchor" href="#check-and-http" aria-label="Permalink to “Check and HTTP”">​</a></h2><p>Check is <strong>POST</strong>; GET is 404. 204 (no update) and 304 (ETag) are not failures. Errors use <code>{ &quot;error&quot;: { &quot;code&quot;, &quot;message&quot;, &quot;details&quot; } }</code>.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to “Capabilities”">​</a></h2><p>Advertise only live adapters: <code>full_package</code> / <code>file_list</code> / <code>patch_package</code> / <code>binary_delta</code> plus <code>accepted_delta_algos</code>. Do not send <code>binary_delta</code> without a Patcher. <code>local_sha256</code> is diff-only.</p><h2 id="adapters" tabindex="-1">Adapters <a class="header-anchor" href="#adapters" aria-label="Permalink to “Adapters”">​</a></h2><p>HTTP, files, hashing, zip, and signature verify are injectable. JSON is <strong>not</strong> an adapter (Jackson, kotlinx.serialization, serde_json, cJSON, nlohmann/json, …). Do not add a second HTTP/JSON stack (axios, OkHttp, Guzzle, Gson, RapidJSON, …). Delta apply and in-use/APK install have no default: Patcher / Replacer only (Go may ship an optional pure-Go Patcher).</p><h2 id="delta-magics" tabindex="-1">Delta magics <a class="header-anchor" href="#delta-magics" aria-label="Permalink to “Delta magics”">​</a></h2><p>Do not cross-decode: <code>KVDIFFHP1</code>, <code>HDIFF13&amp;</code>, <code>BSDIFF40</code>, VCDIFF <code>D6 C3 C4</code>. Unknown magic falls back to the full package. See <a href="/en/faq/delta">FAQ · Delta</a>.</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to “Docker”">​</a></h2><p>SDK packages, install steps, and caller apps do not depend on Docker. Contract tests inject a fake Transport. Swift <code>swift test</code> needs an Apple toolchain.</p><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><p>Admin-plane SDK; store-feed clients; OpenAPI Generator / hey-api clients; browser / Deno updaters; treating this server repository’s <code>main</code> as the Go/PHP/Swift package root.</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};